import struct, sys
def load(path):
    d = open(path,'rb').read()
    hsize,slen,restart,ch,npats,ninsts,flags,speed,bpm = struct.unpack_from('<IHHHHHHHH',d,60)
    off = 60+hsize
    pats=[]
    for p in range(npats):
        plen,fmt,rows,_ = struct.unpack_from('<IBBH',d,off)
        hs = 9
        i = off+hs; cells={}
        for r in range(rows):
            for c in range(ch):
                m = d[i]; i+=1
                if m == 0: continue
                if m & 0x80:
                    note=inst=vol=fx=px=0
                    if m&0x01: note=d[i]; i+=1
                    if m&0x02: inst=d[i]; i+=1
                    if m&0x04: vol=d[i]; i+=1
                    if m&0x08: fx=d[i]; i+=1
                    if m&0x10: px=d[i]; i+=1
                else:
                    note=m; inst=d[i]; vol=d[i+1]; fx=d[i+2]; px=d[i+3]; i+=4
                if note or inst or vol or fx or px: cells[(r,c)]=(note,inst,vol,fx,px)
        off += hs+max(plen, 0)
        # clone stores a bogus packed length: recompute offset from consumption
        pats.append(cells)
    return dict(ch=ch,npats=npats,rows=rows,pats=pats,speed=speed,bpm=bpm,length=slen)
if __name__=='__main__':
    m=load(sys.argv[1])
    print('ch',m['ch'],'pats',m['npats'],'rows',m['rows'],'speed',m['speed'],'bpm',m['bpm'],'len',m['length'])
